INSERT INTO post_metrics (post_id, age_hours, views, likes, replies, reposts, quotes)
SELECT $1, EXTRACT(EPOCH FROM (now()-published_at))/3600, $2,$3,$4,$5,$6
  FROM posts WHERE id=$1;

